window.products.push({"id":886640,"name":"Checkmates Salt and Pepper Shakers","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/71W05xM-keL._AC_SL1500_.jpg","description":"Checkmate Salt and Pepper Shakers by Lorena Agolli On the dining table, salt and pepper are a traditionally paired set of condiments used to enhance the flavour of many European dishes. Like the chess pieces, salt and pepper shakers are matched in a set, with white indicating salt and black for pepper. Often the queen gets an extra shake more than the king, but both are essential to completing a meal.","images":["https://m.media-amazon.com/images/I/71W05xM-keL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"imm Living","source_asin":"B0033PRFPC","category_path":"Home & Kitchen"},"sku":"BM-886640","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B0033PRFPC","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B0033PRFPC","price_pending":true,"merchant_ready":false});
